// Synthetic role cases: assertions describe real hiring distinctions, not exact phrasing.
export const priorityCases=[
 {name:'azure-team',explicitRequirements:[],preferredCapabilities:[/certification/i],job:{title:'Azure Cloud Engineer',description:'Join a team of three cloud engineers modernizing a hospital cloud environment. Design and implement Azure landing zones and hub-and-spoke networks, including routing and private connectivity. Build repeatable infrastructure using Terraform or Bicep. Migrate on-premises applications to Azure with the application teams. Configure Azure Policy and RBAC to maintain governance. Azure certification is preferred. We offer competitive benefits and a collaborative culture.',manager_notes:'This engineer contributes alongside two other cloud engineers; they do not independently own the enterprise architecture.'},required:[/landing zones?/i,/hub.and.spoke/i,/Terraform.*(?:or|\/).*Bicep|Bicep.*(?:or|\/).*Terraform/i],top:/landing|network/i,forbidden:/sole|independent.*enterprise|must.*certif/i},
 {name:'manual-qa',explicitRequirements:[/SQL/i],preferredCapabilities:[/Playwright/i],job:{title:'QA Engineer',description:'Own hands-on manual regression and exploratory testing for billing releases. Create test cases, reproduce defects and communicate release risks to developers. SQL experience is required to validate billing data. Playwright automation is a nice-to-have; this role will not own automation framework development.'},required:[/manual|exploratory/i,/SQL/i],top:/manual|regression|exploratory/i,forbidden:/build.*automation framework|own.*automation framework/i},
 {name:'account-retention',explicitRequirements:[],preferredCapabilities:[/Salesforce/i],job:{title:'Account Manager',description:'Manage renewals for an existing portfolio of midmarket customers. Identify adoption risks, coordinate success plans and negotiate renewals to retain revenue. Partner with support and product to resolve account issues. This is not a new-logo prospecting role. Salesforce experience is preferred.'},required:[/renewal/i,/retention|retain|adoption/i],top:/renewal|retention|retain/i,forbidden:/cold.call|new.logo acquisition|prospecting pipeline/i},
 {name:'warehouse',explicitRequirements:[],preferredCapabilities:[/forklift/i],job:{title:'Warehouse Associate',description:'Pick and pack customer orders accurately. Receive shipments, check quantities against purchase orders and maintain inventory records. Follow documented warehouse safety procedures. Forklift certification is preferred but not required.'},required:[/pick.*pack|pack.*pick/i,/inventory|receive|receiving/i],top:/pick|pack|order/i,forbidden:/manage.*team|warehouse management|mandatory.*forklift|required.*forklift/i},
 {name:'clinical-nurse',explicitRequirements:[/Ohio.*RN|RN.*Ohio|nurs.*licen/i,/BLS/i],preferredCapabilities:[/Epic/i],job:{title:'Registered Nurse',description:'Provide bedside care on a medical-surgical unit. Assess patients, administer medications, monitor changes and coordinate handoffs. An active Ohio RN license is required. BLS certification is required. Epic experience is preferred. New graduates are welcome.'},required:[/patient|bedside/i,/Ohio.*RN|RN.*Ohio|nurs.*licen/i],forbidden:/[2-9]\+? years|ICU|critical.care certification/i},
 {name:'sparse-title',job:{title:'Senior Software Engineer',description:'Join our growing company. We offer competitive benefits, a friendly team and flexible hours.'},empty:true}
];
export function checkPriorityCase(test,items,assert){
 assert.ok(Array.isArray(items)&&items.length<=5,'Unbounded list');
 if(test.empty){assert.equal(items.length,0,'Sparse title invented requirements');return;}
 assert.ok(items.length>0,'No priorities generated');
 const content=items.map(p=>p.title+' '+p.reason).join('\n');
 for(const pattern of test.required||[])assert.match(content,pattern,test.name+' lost a central capability');
 if(test.top)assert.match(items[0].title,test.top,test.name+' elevated a peripheral requirement');
 if(test.forbidden)assert.doesNotMatch(items.map(p=>p.title).join('\n'),test.forbidden,test.name+' introduced unsupported scope');
 for(const pattern of test.explicitRequirements||[])assert.ok(items.some(p=>p.requirement_type==='required'&&pattern.test(p.title)),test.name+' lost an explicit requirement');
 for(const item of items){
  if(item.requirement_type==='required')assert.ok((test.explicitRequirements||[]).some(pattern=>pattern.test(item.title)),test.name+' promoted a responsibility to a mandatory qualification');
  if((test.preferredCapabilities||[]).some(pattern=>pattern.test(item.title)))assert.equal(item.requirement_type,'preferred',test.name+' changed an optional qualification');
  assert.ok(test.job.description.includes(item.source_quote),'Source quotation was not original');assert.ok(item.reason&&item.question);}
}
